mapper.select:
SELECT COUNT(*)
FROM work_invitations
WHERE work_case_id = #{workCaseId}

mapper.delete:
DELETE FROM work_cases
WHERE id = #{workCaseId}
  AND status = 'DRAFT'

mapper.select:
SELECT status     AS status,
       COUNT(*)   AS caseCount
FROM work_cases
WHERE workplace_id = #{workplaceId}
  AND employer_id = #{ownerUserId}
GROUP BY status

SELECT COUNT(*) > 0
FROM workplaces
WHERE id = #{workplaceId}
  AND owner_user_id = #{ownerUserId}
  AND status IN ('ACTIVE', 'INACTIVE')

mapper.sql:
FROM work_cases wc
         LEFT JOIN users w ON w.id = wc.worker_id
WHERE wc.workplace_id = #{workplaceId}
  AND wc.employer_id = #{ownerUserId}

    AND (wc.title LIKE CONCAT('%', #{keyword}, '%')
        OR w.name LIKE CONCAT('%', #{keyword}, '%'))


    AND wc.status = #{status}


    AND DATE(wc.starts_at) >= #{from}


    AND DATE(wc.starts_at) <= #{to}

mapper.select:
SELECT status, amount
FROM escrows
WHERE work_case_id = #{workCaseId}
